mux := http.NewServeMux()
mux.HandleFunc("POST /v1/orders", func(w http.ResponseWriter, r *http.Request) {
    var req OrderRequest                              // DTO = published language
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil { httpError(w, err); return }
    ack, err := orders.Submit(r.Context(), req)       // internal/orders stays private
    writeJSON(w, ack, err)
})
